    <td><button type="button" class="check-action" data-field="did_not_stop" aria-pressed="<?= !empty($team['did_not_stop']) ? 'true' : 'false' ?>"><?= !empty($team['did_not_stop']) ? '✓' : '' ?></button></td><td><button type="button" class="completion" data-field="confirmed" data-state="<?= !empty($team['confirmed']) ? (!empty($team['best_time']) ? 'confirmed' : 'invalid') : 'pending' ?>" aria-label="<?= !empty($team['confirmed']) ? 'Výsledek potvrzen' : 'Rozpracovaný výsledek' ?>"><?= !empty($team['confirmed']) ? (!empty($team['best_time']) ? '✓' : '×') : '?' ?></button></td></tr><?php endforeach; ?></tbody></table></div>
